import React from 'react';
import './Header.css'; // Add your own styling here

const Header = () => {
  return (
    <header className="header">
      <div className="logo">
        <img src="/logo.png" alt="logo" /> {/* Replace with actual logo */}
      </div>
      <div className="search-bar">
        <input type="text" placeholder="Search" />
        <button type="submit"><i className="fa fa-search"></i></button>
      </div>
      <nav className="nav-links">
        <a href="#">Home</a>
        <a href="#">About Us</a>
        <a href="#">Sarees</a>
        <a href="#">Jewellery</a>
      </nav>
      
    </header>
  );
}

export default Header;
